  def batteryIn_Id : Art.PortId
  def chargerIn_Id : Art.PortId
  def eligibilityOut_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var eligibilityOut: Drone_Lifecycle_Energy_Governor.ChargeEligibility = $

  def put_eligibilityOut(value : Drone_Lifecycle_Energy_Governor.ChargeEligibility) : Unit = {
    Contract(
      Modifies(eligibilityOut),
      Ensures(
        eligibilityOut == value
      )
    )
    Spec {
      eligibilityOut = value
    }

    Art.putValue(eligibilityOut_Id, Drone_Lifecycle_Energy_Governor.ChargeEligibility_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

